mod sparse;mod scheduler;mod bqi;mod bridge;
#[cfg(test)]mod tests{
use super::*;use sparse::{Charge,Owner};use scheduler::{Row,ProofTerm};use std::time::{Instant,Duration};
#[derive(Default)]struct Ledger{work:u64,bytes:u64,checks:u64,stop:Option<u64>}
impl Owner for Ledger{fn reserve(&mut self,q:Charge)->Result<(),()>{self.work+=q.work;self.bytes+=q.bytes;Ok(())}fn check(&mut self)->Result<(),()>{self.checks+=1;if self.stop==Some(self.checks){Err(())}else{Ok(())}}}
fn lim()->bridge::Limits{bridge::Limits{variables:10000,generators:10000,terms:1000,degree:128,proof:1000,wire:65536,work:1_000_000_000,bytes:200_000_000}}
fn deadline()->Instant{Instant::now()+Duration::from_secs(10)}
fn row()->Row{Row{polynomial:vec![vec![129],vec![0,1]],proof:vec![ProofTerm{generator:0,multiplier:vec![]}]}}
#[test]fn degree_lex_to_lex_preserves_zero_generators_and_high_indices(){let r=row();let g=vec![r.polynomial.clone(),vec![]];let mut o=Ledger::default();let c=bridge::certify(130,&g,&r,lim(),bqi::Limits::software(),deadline(),&mut o);assert_eq!(c.result,Ok(()));assert_eq!(String::from_utf8(c.raw).unwrap(),"BQI1 130 2 2 2 0 1 1 129 0 2 2 0 1 1 129 1 0 0\n");assert_eq!(c.charge.work,o.work);assert_eq!(c.charge.bytes,o.bytes);assert!(!c.audit.unwrap().source_authenticated);}
#[test]fn target_and_source_mutations_fail_arithmetic(){let mut r=row();let g=vec![r.polynomial.clone()];r.polynomial=vec![vec![]];let c=bridge::certify(130,&g,&r,lim(),bqi::Limits::software(),deadline(),&mut Ledger::default());assert_eq!(c.result,Err(bridge::Failure::Checker));assert_eq!(c.audit.unwrap().result,Err(bqi::Failure::EqualityMismatch));let r=row();let g=vec![vec![vec![128]]];assert_eq!(bridge::certify(130,&g,&r,lim(),bqi::Limits::software(),deadline(),&mut Ledger::default()).result,Err(bridge::Failure::Checker));}
#[test]fn malformed_origins_duplicates_order_and_multipliers_rejected(){let g=vec![row().polynomial];for mode in 0..4{let mut r=row();match mode{0=>r.proof[0].generator=1,1=>r.proof.push(ProofTerm{generator:0,multiplier:vec![]}),2=>r.polynomial.reverse(),_=>r.proof[0].multiplier=vec![1,1]};assert_eq!(bridge::certify(130,&g,&r,lim(),bqi::Limits::software(),deadline(),&mut Ledger::default()).result,Err(bridge::Failure::Malformed));}}
#[test]fn every_owner_refusal_retains_charges_and_never_passes(){let r=row();let g=vec![r.polynomial.clone()];let mut o=Ledger::default();let c=bridge::certify(130,&g,&r,lim(),bqi::Limits::software(),deadline(),&mut o);assert_eq!(c.result,Ok(()));let count=o.checks;for stop in 1..=count{let mut o=Ledger{stop:Some(stop),..Default::default()};let c=bridge::certify(130,&g,&r,lim(),bqi::Limits::software(),deadline(),&mut o);assert_eq!(c.result,Err(bridge::Failure::Owner));assert_eq!(c.charge.work,o.work);assert_eq!(c.charge.bytes,o.bytes);if stop==count{assert!(c.audit.unwrap().result.is_ok());}}}
#[test]fn wire_work_deadline_and_checker_caps_stay_finite(){let r=row();let g=vec![r.polynomial.clone()];for cap in [0,4,5,10,20]{let mut l=lim();l.wire=cap;let c=bridge::certify(130,&g,&r,l,bqi::Limits::software(),deadline(),&mut Ledger::default());assert_eq!(c.result,Err(bridge::Failure::Cap));assert!(c.raw.len()<=cap);}let mut l=lim();l.work=100;assert_eq!(bridge::certify(130,&g,&r,l,bqi::Limits::software(),deadline(),&mut Ledger::default()).result,Err(bridge::Failure::Cap));assert_eq!(bridge::certify(130,&g,&r,lim(),bqi::Limits::software(),Instant::now(),&mut Ledger::default()).result,Err(bridge::Failure::Deadline));let mut checker=bqi::Limits::software();checker.variables=128;assert_eq!(bridge::certify(130,&g,&r,lim(),checker,deadline(),&mut Ledger::default()).result,Err(bridge::Failure::Checker));}
#[test]fn actual_scheduler_rows_replay_on_same_cumulative_owner(){let g=vec![vec![vec![128],vec![128,129]],vec![vec![129],vec![128,129]]];let mut owner=Ledger::default();let d=deadline();let l=scheduler::Limits{batch_rows:256,batch_ops:4096,batches:64,variables:256,generators:64,basis:64,tasks:20000,terms:512,proof:4096,degree:2,work:20_000_000,bytes:200_000_000};let a=scheduler::run(130,&g,l,d,&mut owner);assert!(!a.complete);assert!(a.row_xors>0);let r=a.basis.iter().find(|r|r.polynomial==vec![vec![128],vec![129]]).unwrap();assert!(r.proof.len()>1);let before=owner.work;let c=bridge::certify(130,&g,r,lim(),bqi::Limits::software(),d,&mut owner);assert_eq!(c.result,Ok(()));assert_eq!(owner.work,before+c.charge.work);assert!(!a.complete);}
}
